CREATE TABLE users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,profile jsonb NOT NULL);
CREATE UNIQUE INDEX users_email_fold ON users(lower(email));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE password_resets(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE INDEX password_resets_expiry ON password_resets(expires_at);
CREATE TABLE workspaces(id uuid PRIMARY KEY,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),version bigint NOT NULL DEFAULT 1 CHECK(version>0),next_issue_number bigint NOT NULL DEFAULT 1 CHECK(next_issue_number>0));
CREATE TABLE workspace_members(workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,user_id));
CREATE INDEX memberships_user ON workspace_members(user_id,workspace_id);
CREATE TABLE teams(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE TABLE team_members(workspace_id uuid NOT NULL,team_id uuid NOT NULL,user_id uuid NOT NULL,PRIMARY KEY(team_id,user_id),FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id),FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) ON DELETE CASCADE);
CREATE TABLE stages(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,team_id uuid NOT NULL,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),kind text NOT NULL CHECK(kind IN ('backlog','planned','active','done','cancelled')),position bigint NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id),UNIQUE(workspace_id,id),UNIQUE(workspace_id,team_id,id));
CREATE INDEX stages_team ON stages(workspace_id,team_id,position,id);
CREATE TABLE labels(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100),color text NOT NULL CHECK(length(color)<=40),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE TABLE projects(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),description text NOT NULL CHECK(octet_length(description)<=100000),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE TABLE project_teams(workspace_id uuid NOT NULL,project_id uuid NOT NULL,team_id uuid NOT NULL,PRIMARY KEY(project_id,team_id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id),UNIQUE(workspace_id,project_id,team_id));
CREATE TABLE milestones(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,project_id uuid NOT NULL,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),deadline timestamptz,version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),UNIQUE(workspace_id,id),UNIQUE(workspace_id,project_id,id));
CREATE TABLE sprints(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,team_id uuid NOT NULL,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),goal text NOT NULL CHECK(octet_length(goal)<=100000),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at),state text NOT NULL CHECK(state IN ('planned','active','completed','archived')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id),UNIQUE(workspace_id,id),UNIQUE(workspace_id,team_id,id));
CREATE TABLE sprint_outcomes(workspace_id uuid NOT NULL,sprint_id uuid PRIMARY KEY,total bigint NOT NULL CHECK(total>=0),completed bigint NOT NULL CHECK(completed>=0 AND completed<=total),effort bigint NOT NULL CHECK(effort>=0),FOREIGN KEY(workspace_id,sprint_id) REFERENCES sprints(workspace_id,id));
CREATE TABLE issues(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),number bigint NOT NULL CHECK(number>0),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 500),description text NOT NULL CHECK(octet_length(description)<=100000),team_id uuid NOT NULL,stage_id uuid NOT NULL,assignee uuid REFERENCES users(id),priority text NOT NULL CHECK(priority IN ('none','low','normal','high','urgent')),estimate bigint CHECK(estimate BETWEEN 0 AND 4294967295),deadline timestamptz,project_id uuid,milestone_id uuid,sprint_id uuid,parent_id uuid,position bigint NOT NULL,deleted_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),reminder_generation bigint NOT NULL DEFAULT 1 CHECK(reminder_generation>0),UNIQUE(workspace_id,id),UNIQUE(workspace_id,number),CHECK(parent_id IS DISTINCT FROM id),CHECK(milestone_id IS NULL OR project_id IS NOT NULL),FOREIGN KEY(workspace_id,assignee) REFERENCES workspace_members(workspace_id,user_id),FOREIGN KEY(workspace_id,team_id,stage_id) REFERENCES stages(workspace_id,team_id,id),FOREIGN KEY(workspace_id,project_id,team_id) REFERENCES project_teams(workspace_id,project_id,team_id),FOREIGN KEY(workspace_id,project_id,milestone_id) REFERENCES milestones(workspace_id,project_id,id),FOREIGN KEY(workspace_id,team_id,sprint_id) REFERENCES sprints(workspace_id,team_id,id),FOREIGN KEY(workspace_id,parent_id) REFERENCES issues(workspace_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX issues_board ON issues(workspace_id,team_id,stage_id,position,id) WHERE deleted_at IS NULL;
CREATE INDEX issues_deadline ON issues(workspace_id,deadline,id) WHERE deleted_at IS NULL AND deadline IS NOT NULL;
CREATE INDEX issues_assignee ON issues(workspace_id,assignee,id) WHERE deleted_at IS NULL;
CREATE INDEX issues_project ON issues(workspace_id,project_id,id);
CREATE INDEX issues_sprint ON issues(workspace_id,sprint_id,id);
CREATE INDEX issues_parent ON issues(workspace_id,parent_id);
CREATE INDEX issues_search ON issues USING gin(to_tsvector('simple',title || ' ' || description));
CREATE TABLE issue_labels(workspace_id uuid NOT NULL,issue_id uuid NOT NULL,label_id uuid NOT NULL,PRIMARY KEY(issue_id,label_id),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),FOREIGN KEY(workspace_id,label_id) REFERENCES labels(workspace_id,id));
CREATE TABLE issue_dependencies(workspace_id uuid NOT NULL,issue_id uuid NOT NULL,dependency_id uuid NOT NULL,CHECK(issue_id<>dependency_id),PRIMARY KEY(issue_id,dependency_id),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),FOREIGN KEY(workspace_id,dependency_id) REFERENCES issues(workspace_id,id));
CREATE INDEX dependencies_reverse ON issue_dependencies(workspace_id,dependency_id,issue_id);
CREATE TABLE issue_followers(workspace_id uuid NOT NULL,issue_id uuid NOT NULL,user_id uuid NOT NULL,PRIMARY KEY(issue_id,user_id),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) ON DELETE CASCADE);
CREATE TABLE source_links(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,issue_id uuid NOT NULL,url text NOT NULL,title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 500),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),UNIQUE(issue_id,url,title));
CREATE TABLE comments(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,issue_id uuid NOT NULL,author uuid NOT NULL REFERENCES users(id),body text NOT NULL CHECK(octet_length(body) BETWEEN 1 AND 100000),created_at timestamptz NOT NULL,edited_at timestamptz,version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),UNIQUE(workspace_id,id),UNIQUE(workspace_id,issue_id,id));
CREATE INDEX comments_issue ON comments(workspace_id,issue_id,created_at,id);
CREATE TABLE comment_mentions(workspace_id uuid NOT NULL,comment_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),PRIMARY KEY(comment_id,user_id),FOREIGN KEY(workspace_id,comment_id) REFERENCES comments(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE time_entries(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,issue_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),minutes bigint NOT NULL CHECK(minutes BETWEEN 1 AND 1440),note text NOT NULL CHECK(octet_length(note)<=10000),logged_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),UNIQUE(workspace_id,id));
CREATE INDEX time_issue ON time_entries(workspace_id,issue_id,logged_at,id);
CREATE TABLE attachments(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,issue_id uuid NOT NULL,comment_id uuid,uploader_id uuid NOT NULL REFERENCES users(id),filename text NOT NULL CHECK(octet_length(filename) BETWEEN 1 AND 200),content_type text NOT NULL,bytes bytea NOT NULL CHECK(octet_length(bytes)<=5242880),created_at timestamptz NOT NULL,FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id),FOREIGN KEY(workspace_id,issue_id,comment_id) REFERENCES comments(workspace_id,issue_id,id) ON DELETE CASCADE);
CREATE INDEX attachments_issue ON attachments(workspace_id,issue_id,comment_id);
CREATE TABLE invitations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')),token_hash text NOT NULL,expires_at timestamptz NOT NULL,state text NOT NULL CHECK(state IN ('pending','accepted','cancelled','expired')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE UNIQUE INDEX pending_invitation_email ON invitations(workspace_id,lower(email)) WHERE state='pending';
CREATE INDEX invitations_expiry ON invitations(expires_at) WHERE state='pending';
CREATE TABLE saved_views(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),owner uuid NOT NULL REFERENCES users(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),shared bool NOT NULL,filter jsonb NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE TABLE alert_preferences(workspace_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),assignment bool NOT NULL DEFAULT true,reply bool NOT NULL DEFAULT true,change bool NOT NULL DEFAULT true,mention bool NOT NULL DEFAULT true,deadline bool NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,user_id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE notifications(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES users(id),issue_id uuid,kind text NOT NULL CHECK(kind IN ('assignment','reply','change','mention','deadline')),message text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL,dedup_key text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,dedup_key),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id));
CREATE INDEX notifications_inbox ON notifications(workspace_id,user_id,created_at DESC,id);
CREATE TABLE activity(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),actor uuid NOT NULL REFERENCES users(id),action text NOT NULL,entity_id uuid,at timestamptz NOT NULL,fields jsonb NOT NULL DEFAULT '[]');
CREATE INDEX activity_entity ON activity(workspace_id,entity_id,at,id);
CREATE INDEX activity_timeline ON activity(workspace_id,at DESC,id);
CREATE TABLE integrations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),webhook_url text NOT NULL,secret text NOT NULL,enabled bool NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(workspace_id,id));
CREATE TABLE inbound_deliveries(workspace_id uuid NOT NULL,integration_id uuid NOT NULL,delivery_id uuid NOT NULL,request_hash text NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(integration_id,delivery_id),FOREIGN KEY(workspace_id,integration_id) REFERENCES integrations(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE operation_keys(workspace_id uuid NOT NULL REFERENCES workspaces(id),actor uuid NOT NULL REFERENCES users(id),key text NOT NULL CHECK(octet_length(key) BETWEEN 1 AND 200),request jsonb NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,actor,key));
